function DataView() {
  const [selected,setSelected]=useState(2); const s=pipelineStages[selected]; const records=[`{ observed: "06/12", temperature: "24C", field: "North plot", humidity: null }`,`{ observed: "06-12T08:00:00", temperature: "24 °C", field: "North plot", humidity: null }`,`{ observed: "06-12T08:00:00", temperature: "24 °C", field: "North plot", humidity: null, quality: "needs-review" }`,`{ observed_day: "06-12", temperature_c: 24, field_key: "north_plot", quality: "needs-review" }`,`{ table: "daily_observations", partition: "06-12/north_plot" }`,`{ weekly_mean_c: 25.9, source_rows: 7, review_flags: 2 }`];
  const notes=[['Field CSV, forms, devices','Read and retain source context','Timestamped raw event'],['Timestamped events','Parse structure and record arrival','Bronze raw record'],['Bronze records','Check required values, ranges, and duplicate keys','Accepted record + quality notes'],['Validated records','Normalize dates, units, and field names','Silver clean record'],['Silver clean records','Retain lineage and access context','Queryable dataset'],['Queryable data','Summarize patterns with limitations','Human-readable trend']][selected];
  return <div className="workspace-body data-workspace"><div className="workspace-view-heading"><span className="workspace-kicker">DATA SYSTEMS WORKSHOP · PYTHON / SQL / POSTGRESQL / DATA QUALITY / ETL</span><p>Follow an illustrative observation through a pipeline. The selected sample transformation executes in this browser; this does not represent a deployed production system.</p></div><div className="pipeline-intro"><div><span className="workspace-kicker">ASSEMBLING SYSTEM · SELECT A STAGE</span><p>Sources → Ingestion → Validation → Transformation → Storage → Analytics</p></div><span className="pipeline-key"><i/> SYNTHETIC RECORD IN MOTION</span></div><PipelineAssembly stages={pipelineStages} selected={selected} onSelect={setSelected}/><div className="pipeline-detail"><div className="pipeline-detail-main"><span className="workspace-kicker">STATION {String(selected+1).padStart(2,'0')} / {s.kind}</span><h3>{s.label}</h3><p>{['Collect records from people, devices, or existing systems.','Bring records into a controlled processing boundary.','Check required fields, ranges, and duplicate keys.','Standardize units and align records to a useful schema.','Store data with access boundaries, retention, and lineage.','Summarize trends without losing context or limitations.'][selected]}</p><div className="stage-io"><div><span>INPUT</span><b>{notes[0]}</b></div><ArrowRight/><div><span>OPERATION</span><b>{notes[1]}</b></div><ArrowRight/><div><span>OUTPUT</span><b>{notes[2]}</b></div></div></div><div className="record-transform"><span>SYNTHETIC RECORD · BEFORE → AFTER</span><div><small>INPUT SAMPLE</small><code>{records[Math.max(0,selected-1)]}</code></div><ArrowRight/><div><small>OUTPUT SAMPLE</small><code>{records[selected]}</code></div></div></div><div className="medallion"><div className="medallion-title"><span className="workspace-kicker">THREE LAYERS · ONE LINEAGE</span><p>Keep raw history, clean records, and decision-ready views distinct.</p></div><article className="medal"><span>BRONZE / RAW</span><strong>Keep the source</strong><small>Original event + arrival context</small><div className="medal-bar bronze"/></article><ArrowRight/><article className="medal"><span>SILVER / CLEAN</span><strong>Make it consistent</strong><small>Validated schema + quality notes</small><div className="medal-bar silver"/></article><ArrowRight/><article className="medal"><span>GOLD / ANALYTICS</span><strong>Serve a question</strong><small>Aggregated, use-ready measures</small><div className="medal-bar gold"/></article></div><div className="data-project-heading"><span className="workspace-kicker">DATA PROJECT SPOTLIGHTS · HONEST STATUS</span><p>These project directions connect the pipeline demonstration to the wider portfolio. Repositories and implementation status remain unverified where shown.</p></div><div className="data-project-notes"><article><span className="workspace-kicker">PROJECT DIRECTION · DATA QUALITY</span><h3>Data Normalization Assistant</h3><p>A Streamlit and pandas direction for inspecting missing values and duplicates. A public repository or implementation was not verified in this project.</p></article><article><span className="workspace-kicker">PROJECT DIRECTION · WAREHOUSING</span><h3>Healthcare Data Warehouse</h3><p>A bronze, silver, and gold data-layer direction. This workspace demonstrates transformations only on its synthetic browser sample.</p></article><article><span className="workspace-kicker">PROJECT REFERENCES · API / DATABASE</span><h3>Expense Tracker API · Escrow Backend · PostgreSQL App</h3><p>FastAPI, PostgreSQL, Flask, SQLAlchemy, and Docker project directions mentioned in the supplied project brief; repository links and implementation states are not verified here.</p></article></div></div>;
}
