  if(kind==='agriculture') { const rows=readings.filter(row=>filter==='All'||row.crop===filter); return <div className="workspace-body context-workspace"><div className="workspace-view-heading"><span className="workspace-kicker">SHAMBASENSE · AGRICULTURAL OBSERVATION PROTOTYPE</span><p>Explore generated field records. They are not verified agricultural advice or model predictions.</p></div><div className="workspace-feature-split"><article className="workspace-module"><h3>Record first. Interpret carefully.</h3><p>Crop, field, and season context would help make an observation useful. Here, crop selection filters a small synthetic sample.</p><div className="workspace-tabs" aria-label="Filter sample crop">{['All','Maize','Beans','Tomato'].map(item=><button key={item} aria-pressed={filter===item} className={filter===item?'active':''} onClick={()=>setFilter(item)}>{item}</button>)}</div><Chart values={rows.map(row=>row.value)}/><div className="readings-list">{rows.map(row=><span key={row.day}>{row.day} · {row.field} · {row.crop} · {row.value}°</span>)}</div><button className="workspace-next" onClick={()=>setChecked(!checked)}>{checked?<Check size={15}/>:<Plus size={15}/>} {checked?'Sample note added':'Add a synthetic field note'}</button></article><figure className="context-photo"><img src="/agriculture.jpeg" alt="Victor outdoors in a wooded setting"/><figcaption>Victor outdoors · supplied photograph, shown as a personal field note rather than crop evidence.</figcaption></figure></div><figure className="context-photo context-photo-wide"><img src="/8ae3d177-4465-461c-9200-a86611e43d4e.jpeg" alt="Victor meeting llamas outdoors"/><figcaption>Victor meeting llamas during an outdoor visit. This image is contextual and is not an agricultural project result.</figcaption></figure></div>; }
  const values=device==='Sensor 07'?[20,22,21,23,24,32,25]:[22,22,23,24,24,25,24];
