  if(kind==='security') return <div className="workspace-body simple-workspace"><div className="workspace-kicker"><ShieldCheck size={18}/> RESPONSIBLE ENGINEERING</div><h3>Trust is an engineering decision.</h3><p>Privacy and security belong in the design from the first data field—not as polish at the end.</p><div className="principle-grid">{[['01','Minimize data','Collect only what a feature needs; define retention deliberately.'],['02','Validate every boundary','Treat API input as untrusted; separate authentication from authorization.'],['03','Protect the whole path','Use careful mobile storage, scoped access, and safe IoT data flows.']].map(([num,title,text])=><article key={num}><b>{num}</b><h4>{title}</h4><p>{text}</p></article>)}</div></div>;
